<?php require_once 'functions.php'; require_login(); [$items,$total]=cart_items($koneksi); if(!$items) redirect('keranjang.php'); $title='Checkout';$error='';$alamat='';$metode='sandbox_va';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$alamat=trim($_POST['alamat']??'');$metode=$_POST['metode']??'sandbox_va';$allowed=['sandbox_va','sandbox_ewallet','sandbox_qris'];if(!in_array($metode,$allowed,true))$metode='sandbox_va';if(strlen($alamat)<10)$error='Alamat pengiriman minimal 10 karakter.';else{$koneksi->begin_transaction();try{$check=$koneksi->prepare('SELECT id_produk,nama_produk,harga,stok FROM produk WHERE id_produk=? FOR UPDATE');$insert=$koneksi->prepare("INSERT INTO pesanan(id_user,total,alamat,status) VALUES(?,?,?,'pending')");$uid=$_SESSION['user']['id_user'];$insert->bind_param('ids',$uid,$total,$alamat);$insert->execute();$orderId=$koneksi->insert_id;$detail=$koneksi->prepare('INSERT INTO detail_pesanan(id_pesanan,id_produk,jumlah,harga) VALUES(?,?,?,?)');$stock=$koneksi->prepare('UPDATE produk SET stok=stok-? WHERE id_produk=? AND stok>=?');foreach($items as $i){$id=$i['p']['id_produk'];$qty=$i['qty'];$check->bind_param('i',$id);$check->execute();$fresh=$check->get_result()->fetch_assoc();if(!$fresh||$fresh['stok']<$qty)throw new Exception('Stok produk berubah. Silakan ulangi checkout.');$price=$fresh['harga'];$detail->bind_param('iiid',$orderId,$id,$qty,$price);$detail->execute();$stock->bind_param('iii',$qty,$id,$qty);$stock->execute();if($stock->affected_rows!==1)throw new Exception('Gagal memperbarui stok.');}$ref='JD-'.date('YmdHis').'-'.$orderId.'-'.random_int(100,999);$pay=$koneksi->prepare('INSERT INTO pembayaran(id_pesanan,metode,status,reference) VALUES(?,? ,"pending",?)');$pay->bind_param('iss',$orderId,$metode,$ref);$pay->execute();$koneksi->commit();unset($_SESSION['keranjang']);redirect('pembayaran.php?id='.$orderId);}catch(Throwable $ex){$koneksi->rollback();$error=$ex->getMessage();}}}include 'header.php'; ?>
<div class="container narrow"><h1>Checkout</h1><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><div class="panel"><h3>Ringkasan Pesanan</h3><?php foreach($items as $i):?><div class="summary-row"><span><?=e($i['p']['nama_produk'])?> × <?=$i['qty']?></span><b><?=rupiah($i['subtotal'])?></b></div><?php endforeach;?><hr><div class="summary-row total"><span>Total</span><strong><?=rupiah($total)?></strong></div><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Alamat Pengiriman</label><textarea name="alamat" required><?=e($alamat)?></textarea><label>Metode Pembayaran</label><select name="metode"><option value="sandbox_va" <?=$metode==='sandbox_va'?'selected':''?>>Virtual Account (Sandbox)</option><option value="sandbox_ewallet" <?=$metode==='sandbox_ewallet'?'selected':''?>>E-Wallet (Sandbox)</option><option value="sandbox_qris" <?=$metode==='sandbox_qris'?'selected':''?>>QRIS (Sandbox)</option></select><button class="btn full">Buat Pesanan & Lanjut Bayar</button></form></div></div><?php include 'footer.php'; ?>
